// isocline: the 20 degree isoclines of a torus, the direction tilted 30° from its axis, as curves
export function c013(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(profile, "c1", { "center" : vector(10, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    const up = newSketchOnPlane(context, id + "up", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 0.5, 0.866025)) });
    skLineSegment(up, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(up);
    isocline(context, id + "iso1", { "faces" : qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "direction" : qCreatedBy(id + "up", EntityType.EDGE), "oppositeDirection" : false, "angle" : 20 * degree, "split" : false });
}
